(async () => {
  document.querySelector(".cb-split-bar .cb-split-btn--primary").click();
  const lists = () => document.querySelectorAll(".cb-split-lists > div");
  for (let i = 0; i < 100 && !lists()[1]?.querySelector(".cb-split-item"); i++) await new Promise((r) => setTimeout(r, 100));
  const row = [...lists()[1].querySelectorAll(".cb-split-item")].find((b) => !b.disabled && !b.textContent.includes("너불"));
  const name = row.querySelector("b").textContent;
  row.click();
  return name;
})()

